package com.example.auth.repository;

import com.example.auth.entity.Token;
import com.example.auth.entity.TokenType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

@Repository
public interface TokenRepository extends JpaRepository<Token, Long> {

    Optional<Token> findByTokenValue(String tokenValue);

    List<Token> findByUserIdAndTokenType(String userId, TokenType tokenType);

    List<Token> findByUserId(String userId);

    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.tokenValue = :tokenValue AND t.isRevoked = false AND t.isConsumed = false AND t.expiresAt > :now")
    int revokeToken(@Param("tokenValue") String tokenValue, @Param("now") Instant now);

    @Modifying
    @Query("UPDATE Token t SET t.isConsumed = true WHERE t.tokenValue = :tokenValue AND t.isConsumed = false AND t.isRevoked = false AND t.expiresAt > :now")
    int consumeToken(@Param("tokenValue") String tokenValue, @Param("now") Instant now);

    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.userId = :userId")
    int revokeAllByUserId(@Param("userId") String userId);

    @Modifying
    @Query("DELETE FROM Token t WHERE t.expiresAt < :now OR t.isRevoked = true OR t.isConsumed = true")
    int deleteExpiredOrInvalidTokens(@Param("now") Instant now);

    @Query("SELECT t FROM Token t WHERE t.tokenValue = :tokenValue AND t.isRevoked = false AND t.isConsumed = false AND t.expiresAt > :now")
    Optional<Token> findValidToken(@Param("tokenValue") String tokenValue, @Param("now") Instant now);
}
