package com.example.auth.service;

import com.example.auth.dto.*;
import com.example.auth.entity.Token;
import com.example.auth.entity.TokenType;
import com.example.auth.repository.TokenRepository;
import jakarta.persistence.EntityNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.security.SecureRandom;
import java.time.Instant;
import java.util.Base64;
import java.util.List;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;
    private final SecureRandom secureRandom = new SecureRandom();

    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    private String generateToken() {
        byte[] bytes = new byte[32];
        secureRandom.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    @Transactional
    public LoginResponse login(LoginRequest request) {
        String userId = request.getUsername();
        Instant now = Instant.now();

        // Generate all three tokens
        String accessTokenValue = generateToken();
        String refreshTokenValue = generateToken();
        String oneTimeTokenValue = generateToken();

        // Create and save tokens atomically
        Token accessToken = new Token(accessTokenValue, userId, TokenType.ACCESS, now, now.plusSeconds(600));
        Token refreshToken = new Token(refreshTokenValue, userId, TokenType.REFRESH, now, now.plusSeconds(86400));
        Token oneTimeToken = new Token(oneTimeTokenValue, userId, TokenType.ONE_TIME, now, now.plusSeconds(300));

        tokenRepository.save(accessToken);
        tokenRepository.save(refreshToken);
        tokenRepository.save(oneTimeToken);

        return new LoginResponse(accessTokenValue, oneTimeTokenValue);
    }

    @Transactional
    public RenewResponse renew(String refreshTokenValue) {
        Instant now = Instant.now();

        if (refreshTokenValue == null || refreshTokenValue.isBlank()) {
            throw new SecurityException("Refresh token is missing");
        }

        // Atomically revoke the refresh token if it's valid
        int revoked = tokenRepository.revokeToken(refreshTokenValue, now);
        if (revoked != 1) {
            throw new SecurityException("Refresh token is invalid, expired, or already used");
        }

        // Find the revoked token to get the user ID
        Token oldRefreshToken = tokenRepository.findByTokenValue(refreshTokenValue)
                .orElseThrow(() -> new SecurityException("Refresh token not found"));

        String userId = oldRefreshToken.getUserId();

        // Generate new tokens
        String newAccessTokenValue = generateToken();
        String newRefreshTokenValue = generateToken();

        Token newAccessToken = new Token(newAccessTokenValue, userId, TokenType.ACCESS, now, now.plusSeconds(600));
        Token newRefreshToken = new Token(newRefreshTokenValue, userId, TokenType.REFRESH, now, now.plusSeconds(86400));

        tokenRepository.save(newAccessToken);
        tokenRepository.save(newRefreshToken);

        return new RenewResponse(newAccessTokenValue);
    }

    @Transactional
    public ValidateTokenResponse validateToken(String tokenValue) {
        Instant now = Instant.now();

        if (tokenValue == null || tokenValue.isBlank()) {
            return new ValidateTokenResponse(false, "Token is missing");
        }

        // Atomically consume the token if it's valid
        int consumed = tokenRepository.consumeToken(tokenValue, now);
        if (consumed != 1) {
            // Check why it failed
            Token token = tokenRepository.findByTokenValue(tokenValue).orElse(null);
            if (token == null) {
                return new ValidateTokenResponse(false, "Token not found");
            } else if (token.isConsumed()) {
                return new ValidateTokenResponse(false, "Token already consumed");
            } else if (token.isRevoked()) {
                return new ValidateTokenResponse(false, "Token is revoked");
            } else {
                return new ValidateTokenResponse(false, "Token is expired");
            }
        }

        return new ValidateTokenResponse(true, "Token validated successfully");
    }

    @Transactional
    public LogoutResponse logout(String accessTokenValue) {
        Instant now = Instant.now();

        if (accessTokenValue == null || accessTokenValue.isBlank()) {
            throw new SecurityException("Access token is missing");
        }

        // Verify the access token is valid
        Token accessToken = tokenRepository.findValidToken(accessTokenValue, now).orElse(null);
        if (accessToken == null || accessToken.getTokenType() != TokenType.ACCESS) {
            throw new SecurityException("Access token is invalid");
        }

        String userId = accessToken.getUserId();

        // Revoke all tokens for this user
        tokenRepository.revokeAllByUserId(userId);

        return new LogoutResponse("Logged out successfully");
    }

    @Transactional
    public int cleanupTokens() {
        Instant now = Instant.now();
        int deleted = tokenRepository.deleteExpiredOrInvalidTokens(now);
        System.out.println("[CLEANUP] Deleted " + deleted + " tokens");
        return deleted;
    }
}
EOF"}

