package com.example.auth.controller;

import com.example.auth.dto.*;
import com.example.auth.service.AuthService;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(@RequestBody LoginRequest request, HttpServletResponse response) {
        if (request.getUsername() == null || request.getUsername().isBlank() ||
            request.getPassword() == null || request.getPassword().isBlank()) {
            return ResponseEntity.badRequest().build();
        }

        LoginResult result = authService.login(request);

        Cookie refreshTokenCookie = new Cookie("refreshToken", result.refreshTokenValue());
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400);
        refreshTokenCookie.setPath("/");
        response.addCookie(refreshTokenCookie);

        return ResponseEntity.ok(new LoginResponse(result.accessTokenValue(), result.oneTimeTokenValue()));
    }

    @PostMapping("/renew")
    public ResponseEntity<RenewResponse> renew(@CookieValue(value = "refreshToken", required = false) String refreshTokenCookie,
                                                @RequestHeader(value = "refreshToken", required = false) String refreshTokenHeader,
                                                HttpServletResponse response) {
        // Cookie takes precedence over header
        String refreshTokenValue = refreshTokenCookie != null ? refreshTokenCookie : refreshTokenHeader;

        try {
            RenewResult result = authService.renew(refreshTokenValue);

            Cookie refreshTokenCookieNew = new Cookie("refreshToken", result.newRefreshTokenValue());
            refreshTokenCookieNew.setHttpOnly(true);
            refreshTokenCookieNew.setMaxAge(86400);
            refreshTokenCookieNew.setPath("/");
            response.addCookie(refreshTokenCookieNew);

            return ResponseEntity.ok(new RenewResponse(result.newAccessTokenValue()));
        } catch (SecurityException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<LogoutResponse> logout(@RequestHeader(value = "Authorization", required = false) String authHeader) {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        String accessTokenValue = authHeader.substring(7);

        try {
            LogoutResponse logoutResponse = authService.logout(accessTokenValue);
            return ResponseEntity.ok(logoutResponse);
        } catch (SecurityException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
    }

    @PostMapping("/validate-token")
    public ResponseEntity<ValidateTokenResponse> validateToken(@RequestBody ValidateTokenRequest request) {
        if (request.getToken() == null || request.getToken().isBlank()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(new ValidateTokenResponse(false, "Token is missing"));
        }

        ValidateTokenResponse response = authService.validateToken(request.getToken());
        if (response.isValid()) {
            return ResponseEntity.ok(response);
        } else {
            return ResponseEntity.status(HttpStatus.CONFLICT).body(response);
        }
    }

    private record LoginResult(String accessTokenValue, String refreshTokenValue, String oneTimeTokenValue) {}
    private record RenewResult(String newAccessTokenValue, String newRefreshTokenValue) {}
}
EOF"}

